// Selected official SwitchTopRangeBtn; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class SwitchTopRangeBtn : MonoBehaviour
{
	public Button Buton;

	public WorldStateSwitcher<TopRangeType> StateSwitcher;

	public bool DisabledSwitch;

	public List<TopRangeType> SwitchTopRangeTypes = new List<TopRangeType>
	{
		TopRangeType.Planes,
		TopRangeType.Domain
	};

	protected Action mInnerOnClickAction;
	private bool canSwitchRange;
	public void Configure(bool value) { canSwitchRange = value; }

	public TopRangeType RangeType => StateSwitcher.State;

	private void Awake()
	{


		((UnityEvent)Buton.onClick).AddListener((UnityAction)FireClickEvent);
	}

	private void OnDestroy()
	{
		mInnerOnClickAction = null;
	}

	private void OnEnable()
	{
		if (!DisabledSwitch)
		{
			SwitchToShowPlanes();
			mInnerOnClickAction?.Invoke();
		}
	}

	private void OnDisable()
	{
		SwitchToShowPlanes();
	}

	public void FireClickEvent()
	{
		if (!DisabledSwitch)
		{
			StateSwitcher.SetState(GetNextRangeType());
			mInnerOnClickAction?.Invoke();
		}
	}

	public void SwitchToShowPlanes()
	{
		StateSwitcher.SetState(TopRangeType.Planes);
	}

	public void SwitchToShowDomain()
	{
		StateSwitcher.SetState(TopRangeType.Domain);
	}

	public void SetListener(Action action)
	{
		mInnerOnClickAction = action;
	}

	public void SetActive(bool active = true)
	{
		((Component)this).gameObject.SetActive(canSwitchRange & active);
	}

	public TopRangeType GetNextRangeType()
	{
		int state = (int)StateSwitcher.State;
		int index = (state + 1) % SwitchTopRangeTypes.Count;
		if (SwitchTopRangeTypes[index] == TopRangeType.Domain && !canSwitchRange)
		{
			index = (state + 2) % SwitchTopRangeTypes.Count;
		}
		return SwitchTopRangeTypes[index];
	}
}
}
